CREATE TABLE "User" ("id" TEXT NOT NULL PRIMARY KEY,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"role" TEXT NOT NULL,"clientId" TEXT);
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE UNIQUE INDEX "User_clientId_key" ON "User"("clientId");
CREATE TABLE "Client" ("id" TEXT NOT NULL PRIMARY KEY,"trainerId" TEXT NOT NULL,"name" TEXT NOT NULL,"sex" TEXT,"age" INTEGER,"heightCm" REAL,"weightKg" REAL,"conditions" TEXT NOT NULL,"goals" TEXT NOT NULL,"equipment" TEXT NOT NULL,"schedule" TEXT NOT NULL,"phase" INTEGER NOT NULL DEFAULT 1,"nextRetest" TEXT,"compositionConsent" BOOLEAN NOT NULL DEFAULT false,"compositionFrequencyWeeks" INTEGER NOT NULL DEFAULT 6);
CREATE TABLE "Measurement" ("id" TEXT NOT NULL PRIMARY KEY,"clientId" TEXT NOT NULL,"key" TEXT NOT NULL,"value" REAL NOT NULL,"unit" TEXT NOT NULL,"date" TEXT NOT NULL,"responsible" TEXT NOT NULL,"notes" TEXT NOT NULL DEFAULT '',"meaning" TEXT,"device" TEXT,"conditions" TEXT,"protocol" TEXT,CONSTRAINT "Measurement_clientId_fkey" FOREIGN KEY ("clientId") REFERENCES "Client"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "Measurement_clientId_date_idx" ON "Measurement"("clientId","date");
CREATE TABLE "Assessment" ("id" TEXT NOT NULL PRIMARY KEY,"clientId" TEXT NOT NULL,"key" TEXT NOT NULL,"status" TEXT NOT NULL,"value" REAL,"unit" TEXT,"date" TEXT NOT NULL,"responsible" TEXT NOT NULL,"notes" TEXT NOT NULL DEFAULT '',"protocol" TEXT,"kind" TEXT NOT NULL,CONSTRAINT "Assessment_clientId_fkey" FOREIGN KEY ("clientId") REFERENCES "Client"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "Assessment_clientId_date_idx" ON "Assessment"("clientId","date");
CREATE TABLE "Plan" ("id" TEXT NOT NULL PRIMARY KEY,"clientId" TEXT NOT NULL,"title" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'draft',"startDate" TEXT NOT NULL,"weeks" TEXT NOT NULL,"fitt" TEXT NOT NULL,"weeklySchedule" TEXT NOT NULL,"notes" TEXT NOT NULL DEFAULT '',"source" TEXT NOT NULL DEFAULT 'trainer',"approvedAt" TEXT,"approvedBy" TEXT,CONSTRAINT "Plan_clientId_fkey" FOREIGN KEY ("clientId") REFERENCES "Client"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "Plan_clientId_idx" ON "Plan"("clientId");
CREATE TABLE "TrainingSession" ("id" TEXT NOT NULL PRIMARY KEY,"clientId" TEXT NOT NULL,"planId" TEXT,"date" TEXT NOT NULL,"status" TEXT NOT NULL,"durationMinutes" INTEGER,"rpe" INTEGER,"fatigue" INTEGER,"motivation" INTEGER,"notes" TEXT NOT NULL DEFAULT '',"exercises" TEXT NOT NULL,"trainerNotes" TEXT,CONSTRAINT "TrainingSession_clientId_fkey" FOREIGN KEY ("clientId") REFERENCES "Client"("id") ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT "TrainingSession_planId_fkey" FOREIGN KEY ("planId") REFERENCES "Plan"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE INDEX "TrainingSession_clientId_date_idx" ON "TrainingSession"("clientId","date");
ALTER TABLE "Client" ADD COLUMN "experience" TEXT;
